import{_ as e,o as s,c as a,ag as o}from"./chunks/framework.CxkNbRKf.js";const i="/nada-documentation/images/ind-codelist-list.png",r="/nada-documentation/images/ind-codelist-details.png",d="/nada-documentation/images/ind-codelist-items.png",b=JSON.parse('{"title":"Codelists","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/codelists.md","filePath":"admin-guide/web-ui/codelists.md","lastUpdated":1793155456000}'),n={name:"admin-guide/web-ui/codelists.md"};function l(c,t,h,u,g,m){return s(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="codelists" tabindex="-1">Codelists <a class="header-anchor" href="#codelists" aria-label="Permalink to &quot;Codelists&quot;">​</a></h1><p>A <strong>codelist</strong> is a list of codes and their labels, such as country codes (<code>ALB</code> = Albania) or the categories of sex (<code>F</code> = Female). Columns of a <a href="./data-structures.html">data structure</a> use codelists, so that the catalog can show labels instead of codes in an indicator&#39;s filters, chart and table.</p><p>Codelists can be used by <strong>geography, periodicity, dimension, attribute and measure</strong> columns. See <a href="/nada-documentation/admin-guide/content/indicators-concepts.html#codelist">Key concepts</a> for why other columns do not use them.</p><div class="tip custom-block"><p class="custom-block-title">Using the Metadata Editor?</p><p>Create codelists in the Metadata Editor. They are sent to NADA with the data structure when you publish. Use these screens to check them.</p></div><hr><h2 id="three-ways-to-create-a-codelist" tabindex="-1">Three ways to create a codelist <a class="header-anchor" href="#three-ways-to-create-a-codelist" aria-label="Permalink to &quot;Three ways to create a codelist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Way</th><th>When to use it</th></tr></thead><tbody><tr><td><strong>Import a data structure</strong> that includes its codelists, as JSON or SDMX XML. See <a href="./data-structures.html#import-a-data-structure">Data structures</a>.</td><td>Most cases. The codelists are created together with the data structure. Codelists that already exist are reused.</td></tr><tr><td><strong>Add it by hand</strong> in <strong>Settings → Codelists</strong></td><td>Short lists, or corrections</td></tr><tr><td><strong>Use the API</strong>: <code>POST api/admin/codelists/import_json</code></td><td>Scripts and bulk loads</td></tr></tbody></table><p>The <a href="https://github.com/ihsn/nada-documentation/tree/main/examples/indicators" target="_blank" rel="noreferrer">indicator sample</a> creates its country codelist (<code>WB_CL_REF_AREA_1.0</code>, 183 countries) through the data structure import.</p><hr><h2 id="the-codelists-list" tabindex="-1">The codelists list <a class="header-anchor" href="#the-codelists-list" aria-label="Permalink to &quot;The codelists list&quot;">​</a></h2><p>Go to <strong>Settings → Codelists</strong>. The list shows each codelist&#39;s <strong>Name</strong>, <strong>Agency</strong>, <strong>Latest version</strong>, number of <strong>Versions</strong>, <strong>IDNO</strong>, <strong>Status</strong>, number of <strong>Items</strong>, and the data structures (<strong>DSD</strong>) that use it.</p><p>Search by name, IDNO, agency or version, or filter by <strong>Status</strong>.</p><p><img src="'+i+'" alt=""></p><hr><h2 id="add-a-codelist" tabindex="-1">Add a codelist <a class="header-anchor" href="#add-a-codelist" aria-label="Permalink to &quot;Add a codelist&quot;">​</a></h2><ol><li><p>Go to <strong>Settings → Codelists</strong> and click <strong>Add codelist</strong>.</p></li><li><p>Fill in:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Agency</strong></td><td>The organization that maintains the codelist. Default: <code>NADA</code>.</td></tr><tr><td><strong>Version</strong></td><td>Default: <code>1.0.0</code>.</td></tr><tr><td><strong>Name</strong></td><td>A short identifier, such as <code>CL_SEX</code>. It must be unique for the same agency and version.</td></tr><tr><td><strong>IDNO</strong></td><td>Leave it empty to generate it from agency, name and version. Data structures refer to the codelist by this IDNO.</td></tr><tr><td><strong>Description</strong></td><td>Optional.</td></tr></tbody></table></li><li><p>Save. The codelist opens on its <strong>Codelist details</strong> tab.</p></li></ol><p><img src="'+r+'" alt=""></p><h3 id="add-codes" tabindex="-1">Add codes <a class="header-anchor" href="#add-codes" aria-label="Permalink to &quot;Add codes&quot;">​</a></h3><ol><li>Open the <strong>Codelist items</strong> tab.</li><li>Click <strong>Add item</strong> and fill in: <ul><li><strong>Code</strong>: the value used in the data, such as <code>F</code>. It must be unique within the codelist.</li><li><strong>Default title</strong>: the label shown in the catalog, such as <em>Female</em>.</li><li><strong>Sort order</strong>: the order of the code in filters and lists.</li></ul></li><li>Save. Repeat for each code.</li></ol><p>Use <strong>Translations</strong> on an item to add its label in other languages. The default title is used when a translation is missing.</p><p><img src="'+d+'" alt=""></p><p>The <strong>Groups</strong> tab organizes the items of a long codelist into groups.</p><hr><h2 id="versions-and-status" tabindex="-1">Versions and status <a class="header-anchor" href="#versions-and-status" aria-label="Permalink to &quot;Versions and status&quot;">​</a></h2><p>A codelist has a <strong>status</strong>: <em>Draft</em>, <em>Review</em>, <em>Published</em>, <em>Deprecated</em> or <em>Archived</em>. Once a codelist is <strong>locked</strong>, only its status can be changed: its details, items and groups are read-only.</p><p>To change a locked codelist, create a new version of it, and attach the new version to the data structure.</p><div class="warning custom-block"><p class="custom-block-title">Codes must match the data</p><p>Every code used in an indicator&#39;s data should exist in its codelist. NADA does not check this when data is uploaded.</p></div><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./data-structures.html">Data structures</a>: attach the codelist to a column</li><li><a href="/nada-documentation/admin-guide/content/indicators-concepts.html">Key concepts</a>: codelists, roles and the series key</li></ul>',30)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
